insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-01','en-pre-01',null,0,1,'published',1,'{"id":"en-pre-01","baseId":"en-pre-01","revision":1,"level":"PRE","levelIndex":0,"order":1,"title":"Harf, tovush va ismni harflab aytish","objective":"Ismingizni harflab aytasiz va harf nomi bilan tovushni farqlaysiz.","context":"Yangi o‘quvchi kursga yozilayotganda kotib uning ismini aniqlashtiradi.","prerequisites":[],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/.","A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq.","Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi."],"pattern":"My name is … / How do you spell it? / A — L — I","examples":["My name is Ali.","How do you spell it?","A is a letter.","B is the first letter in bag.","Please spell your name.","L — O — L — A."],"vocabulary":[{"id":"en-pre-01-v0","term":"name","meaning":"ism","ipa":"/neɪm/","collocation":"my name","example":"My name is Ali."},{"id":"en-pre-01-v1","term":"letter","meaning":"harf","ipa":"/ˈletə/","collocation":"a capital letter","example":"A is a letter."},{"id":"en-pre-01-v2","term":"spell","meaning":"harflab aytmoq","ipa":"/spel/","collocation":"spell a name","example":"How do you spell it?"},{"id":"en-pre-01-v3","term":"bag","meaning":"sumka","ipa":"/bæɡ/","collocation":"a school bag","example":"B is the first letter in bag."}],"visuals":[{"kind":"alphabet","title":"Ma’no va tuzilish","items":["My name is … / How do you spell it? / A — L — I","My name is Ali.","How do you spell it?"]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Yangi o‘quvchi kursga yozilayotganda kotib uning ismini aniqlashtiradi.","A is a letter.","Please spell your name."]}],"pronunciation":{"focus":"B harfining bee nomini bag boshidagi qisqa /b/ tovushidan ajrating.","text":"B is the first letter in bag.","audio":"/english-course/v7.23/en-pre-01-dictation.mp3"},"exercises":[{"id":"en-pre-01-choice","type":"choice","skill":"grammar","prompt":"Ismni harflab aytishni so‘rash uchun qaysi gap mos?","answers":["How do you spell it?"],"explanation":"Spell harfma-harf aytishni bildiradi.","hint":"My name is … / How do you spell it? / A — L — I","options":["How do you spell it?","How old are you?","Where are you?"]},{"id":"en-pre-01-gap","type":"grammarFill","skill":"grammar","prompt":"My ___ is Ali.","answers":["name"],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I"},{"id":"en-pre-01-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["My name is Ali."],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I","tokens":["My","name","is","Ali."]},{"id":"en-pre-01-fix","type":"correction","skill":"grammar","prompt":"my name is ali.","answers":["My name is Ali."],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I"},{"id":"en-pre-01-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ism","harf","harflab aytmoq","sumka"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"My name is … / How do you spell it? / A — L — I","left":["name","letter","spell","bag"],"options":["ism","harf","harflab aytmoq","sumka"]},{"id":"en-pre-01-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."}],"reading":{"title":"Harf, tovush va ismni harflab aytish — vaziyat","text":"My name is Ali. I am a new student. My name has three letters: A, L and I. Lola is in my class. Her name has four letters. We write our names with a capital letter at the beginning.","sentences":["My name is Ali.","I am a new student.","My name has three letters: A, L and I.","Lola is in my class.","Her name has four letters.","We write our names with a capital letter at the beginning."],"questions":[{"id":"en-pre-01-reading0","type":"choice","skill":"reading","prompt":"Ali ismi nechta harfdan iborat?","answers":["three"],"explanation":"Matnda A, L, I — uch harf aytilgan.","hint":"My name is … / How do you spell it? / A — L — I","options":["three","four","five"]},{"id":"en-pre-01-reading1","type":"choice","skill":"reading","prompt":"Qaysi ism to‘rt harfdan iborat?","answers":["Lola"],"explanation":"Lola ismi L, O, L, A shaklida yoziladi.","hint":"My name is … / How do you spell it? / A — L — I","options":["Lola","Ali","I"]},{"id":"en-pre-01-evidence","type":"evidence","skill":"reading","prompt":"Ali ismi uch harf ekaniga dalilni tanlang.","answers":["2"],"explanation":"Three letters jumlasi bevosita dalil.","hint":"My name is … / How do you spell it? / A — L — I","options":["My name is Ali.","I am a new student.","My name has three letters: A, L and I.","Lola is in my class.","Her name has four letters.","We write our names with a capital letter at the beginning."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Hello. My name is Lola. Please write my name: L, O, L, A. Ali is my friend. His name is A, L, I.","audio":"/english-course/v7.23/en-pre-01.mp3","synthetic":true,"questions":[{"id":"en-pre-01-listening0","type":"choice","skill":"listening","prompt":"Yozuvdagi asosiy ism nima?","answers":["Lola"],"explanation":"Yozuvda L, O, L, A deyiladi.","hint":"My name is … / How do you spell it? / A — L — I","options":["Lola","Lila","Lena"]},{"id":"en-pre-01-listening1","type":"choice","skill":"listening","prompt":"Lolaning do‘sti kim?","answers":["Ali"],"explanation":"His name is A, L, I jumlasiga quloq tuting.","hint":"My name is … / How do you spell it? / A — L — I","options":["Ali","Aziz","Omar"]},{"id":"en-pre-01-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Lola","Ali"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"My name is … / How do you spell it? / A — L — I","rows":["Asosiy ism","Do‘sti"]},{"id":"en-pre-01-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["B is the first letter in bag."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"My name is … / How do you spell it? / A — L — I","audio":"/english-course/v7.23/en-pre-01-dictation.mp3","transcript":"B is the first letter in bag."}]},"writing":{"task":"Sherigingizga ismingizni va uni qanday harflashingizni ikki yoki uch gapda yozing.","audience":"Sinfdagi sherigingiz","minWords":8,"maxWords":40,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"My name is Lola. My name has four letters. I spell it L, O, L, A.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["My name is Ali.","How do you spell it?","A is a letter."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Ismingizni ayting, uni harflang. Keyin sherigingizdan ismini harflab berishni so‘rang.","seconds":20,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sherigingizga ismingizni va uni qanday harflashingizni ikki yoki uch gapda yozing.","exit":[[{"id":"en-pre-01-exit0","type":"grammarFill","skill":"grammar","prompt":"Ism: L — O — L — A. Yozing.","answers":["Lola"],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I"},{"id":"en-pre-01-exit1","type":"grammarFill","skill":"grammar","prompt":"My ___ is Ali.","answers":["name"],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I"},{"id":"en-pre-01-exit2","type":"grammarFill","skill":"grammar","prompt":"How do you ___ it?","answers":["spell"],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I"},{"id":"en-pre-01-exit3","type":"choice","skill":"grammar","prompt":"Ali ismi nechta harf?","answers":["three"],"explanation":"A, L, I — uchta.","hint":"My name is … / How do you spell it? / A — L — I","options":["three","four","six"]},{"id":"en-pre-01-exit4","type":"choice","skill":"grammar","prompt":"B harfining nomi va /b/ tovushi bir xilmi?","answers":["No"],"explanation":"Harf nomi bee, bag boshida tovush /b/.","hint":"My name is … / How do you spell it? / A — L — I","options":["No","Yes","Always"]}],[{"id":"en-pre-01-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["How do you spell it?"],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I","tokens":["How","do","you","spell","it?"]},{"id":"en-pre-01-exit-b1","type":"grammarFill","skill":"grammar","prompt":"My ___ is Ali.","answers":["name"],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I"},{"id":"en-pre-01-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["B is the first letter in bag."],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I","tokens":["B","is","the","first","letter","in","bag."]},{"id":"en-pre-01-exit-b3","type":"choice","skill":"grammar","prompt":"Ali ismi nechta harf?","answers":["three"],"explanation":"A, L, I — uchta.","hint":"My name is … / How do you spell it? / A — L — I","options":["three","four","six"]},{"id":"en-pre-01-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["L — O — L — A."],"explanation":"Alifboda 26 ta harf bor. Harfning nomi so‘z ichidagi tovush bilan har doim bir xil emas: B — bee, lekin bag boshida /b/. A, E, I, O, U unli harflardir; Y ham ayrim so‘zlarda unli tovushni ifodalaydi. Inglizcha tovushlar soni harflar sonidan ko‘proq. Ismni aytgandan keyin harfma-harf aniqlashtirish mumkin. Bosh harf odam ismining boshida ishlatiladi.","hint":"My name is … / How do you spell it? / A — L — I","tokens":["L","—","O","—","L","—","A."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-pre-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-pre-01","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-02','en-pre-02',null,0,2,'published',1,'{"id":"en-pre-02","baseId":"en-pre-02","revision":1,"level":"PRE","levelIndex":0,"order":2,"title":"Salomlashish va o‘zingizni tanishtirish","objective":"Qisqa salomlashasiz, ismingizni aytasiz va suhbatni yakunlaysiz.","context":"Ikki o‘quvchi yangi sinfda birinchi marta uchrashadi.","prerequisites":["en-pre-01"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi.","I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi.","Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi."],"pattern":"Hello. I’m … / Nice to meet you. / See you.","examples":["Hello. I am Lola.","Hi. I’m Ali.","Nice to meet you.","Good morning, teacher.","You are my classmate.","See you tomorrow."],"vocabulary":[{"id":"en-pre-02-v0","term":"hello","meaning":"salom","ipa":"/həˈləʊ/","collocation":"say hello","example":"Hello. I am Lola."},{"id":"en-pre-02-v1","term":"teacher","meaning":"o‘qituvchi","ipa":"/ˈtiːtʃə/","collocation":"my teacher","example":"Good morning, teacher."},{"id":"en-pre-02-v2","term":"classmate","meaning":"sinfdosh","ipa":"/ˈklɑːsmeɪt/","collocation":"a new classmate","example":"You are my classmate."},{"id":"en-pre-02-v3","term":"tomorrow","meaning":"ertaga","ipa":"/təˈmɒrəʊ/","collocation":"see you tomorrow","example":"See you tomorrow."}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["Hello. I’m … / Nice to meet you. / See you.","Hello. I am Lola.","Hi. I’m Ali."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Ikki o‘quvchi yangi sinfda birinchi marta uchrashadi.","Nice to meet you.","You are my classmate."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Good morning, teacher.","audio":"/english-course/v7.23/en-pre-02-dictation.mp3"},"exercises":[{"id":"en-pre-02-choice","type":"choice","skill":"grammar","prompt":"Ertalab o‘qituvchi bilan salomlashish uchun qaysi gap mos?","answers":["Good morning."],"explanation":"Morning ertalab degani.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Good morning.","Good night.","Goodbye."]},{"id":"en-pre-02-gap","type":"grammarFill","skill":"grammar","prompt":"Nice to ___ you.","answers":["meet"],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Hello. I am Lola."],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you.","tokens":["Hello.","I","am","Lola."]},{"id":"en-pre-02-fix","type":"correction","skill":"grammar","prompt":"I is Lola.","answers":["I am Lola.","I’m Lola."],"explanation":"Hello betaraf, Hi esa erkin salomlashishdir. Good morning ertalab, Good afternoon tushdan keyin ishlatiladi. I am o‘zingiz haqida gapirishni boshlaydi. I’m uning qisqartmasidir. You are va you’re suhbatdoshingiz haqida ishlatiladi. Nice to meet you birinchi uchrashuvda aytiladi. Goodbye yoki See you keyin xayrlashish uchun mos. Good night odatda uxlash oldidan yoki kechki xayrlashishda aytiladi.","hint":"Hello. I’m … / Nice to meet you. / See you."},{"id":"en-pre-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["salom","o‘qituvchi","sinfdosh","ertaga"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Hello. I’m … / Nice to meet you. / See you.","left":["hello","teacher","classmate","tomorrow"],"options":["salom","o‘qituvchi","sinfdosh","ertaga"]},{"id":"en-pre-02-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."}],"reading":{"title":"Salomlashish va o‘zingizni tanishtirish — vaziyat","text":"Hello. I am Lola. Ali is my new classmate. We meet at school in the morning. I say, “Good morning, Ali.” He says, “Hi, Lola. Nice to meet you.” At the end of the lesson, we say, “See you tomorrow.”","sentences":["Hello.","I am Lola.","Ali is my new classmate.","We meet at school in the morning.","I say, “Good morning, Ali.","” He says, “Hi, Lola.","Nice to meet you.","” At the end of the lesson, we say, “See you tomorrow.","”"],"questions":[{"id":"en-pre-02-reading0","type":"choice","skill":"reading","prompt":"O‘quvchilar qayerda uchrashadi?","answers":["at school"],"explanation":"We meet at school — joy bevosita berilgan.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["at school","at home","at a shop"]},{"id":"en-pre-02-reading1","type":"choice","skill":"reading","prompt":"Qachon Good morning deyishadi?","answers":["in the morning"],"e