insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-03','en-pre-03',null,0,3,'published',1,'{"id":"en-pre-03","baseId":"en-pre-03","revision":1,"level":"PRE","levelIndex":0,"order":3,"title":"Sonlar, yosh va telefon raqami","objective":"0–100 oralig‘idagi sonlarni taniysiz, yosh va telefon raqamini aytasiz.","context":"Sport to‘garagi uchun yosh va aloqa ma’lumotlari yoziladi.","prerequisites":["en-pre-02"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Yoshni I am twelve tarzida aytamiz. Inglizchada yosh uchun I have twelve demaymiz. Years old iborasi qo‘shilishi mumkin.","13–19 sonlarida -teen, 20, 30, 40 kabi o‘nliklarda -ty farqiga e’tibor bering. Thirteen va thirty bir xil emas.","Telefon raqamida har bir raqam alohida o‘qiladi. Zero nolning aniq nomidir; oh telefon raqamlarida ham uchraydi."],"pattern":"How old are you? / I am twelve. / zero, one, two …","examples":["I am twelve years old.","How old are you?","My brother is thirteen.","Thirty is three tens.","My number is one, two, zero, five.","There are ten students."],"vocabulary":[{"id":"en-pre-03-v0","term":"twelve","meaning":"o‘n ikki","ipa":"/twelv/","collocation":"twelve years old","example":"I am twelve years old."},{"id":"en-pre-03-v1","term":"thirteen","meaning":"o‘n uch","ipa":"/ˌθɜːˈtiːn/","collocation":"thirteen students","example":"My brother is thirteen."},{"id":"en-pre-03-v2","term":"thirty","meaning":"o‘ttiz","ipa":"/ˈθɜːti/","collocation":"thirty minutes","example":"Thirty is three tens."},{"id":"en-pre-03-v3","term":"number","meaning":"raqam yoki son","ipa":"/ˈnʌmbə/","collocation":"phone number","example":"My number is one, two, zero, five."}],"visuals":[{"kind":"number","title":"Ma’no va tuzilish","items":["How old are you? / I am twelve. / zero, one, two …","I am twelve years old.","How old are you?"]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sport to‘garagi uchun yosh va aloqa ma’lumotlari yoziladi.","My brother is thirteen.","My number is one, two, zero, five."]}],"pronunciation":{"focus":"Thirteen so‘zida ikkinchi bo‘g‘in, thirty so‘zida birinchi bo‘g‘in ko‘proq urg‘u oladi.","text":"Thirty is three tens.","audio":"/english-course/v7.23/en-pre-03-dictation.mp3"},"exercises":[{"id":"en-pre-03-choice","type":"choice","skill":"grammar","prompt":"30 sonining nomini tanlang.","answers":["thirty"],"explanation":"Thirty — uchta o‘nlik.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["thirty","thirteen","three"]},{"id":"en-pre-03-gap","type":"grammarFill","skill":"grammar","prompt":"I ___ twelve years old.","answers":["am"],"explanation":"Yoshni I am twelve tarzida aytamiz. Inglizchada yosh uchun I have twelve demaymiz. Years old iborasi qo‘shilishi mumkin. 13–19 sonlarida -teen, 20, 30, 40 kabi o‘nliklarda -ty farqiga e’tibor bering. Thirteen va thirty bir xil emas. Telefon raqamida har bir raqam alohida o‘qiladi. Zero nolning aniq nomidir; oh telefon raqamlarida ham uchraydi.","hint":"How old are you? / I am twelve. / zero, one, two …"},{"id":"en-pre-03-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I am twelve years old."],"explanation":"Yoshni I am twelve tarzida aytamiz. Inglizchada yosh uchun I have twelve demaymiz. Years old iborasi qo‘shilishi mumkin. 13–19 sonlarida -teen, 20, 30, 40 kabi o‘nliklarda -ty farqiga e’tibor bering. Thirteen va thirty bir xil emas. Telefon raqamida har bir raqam alohida o‘qiladi. Zero nolning aniq nomidir; oh telefon raqamlarida ham uchraydi.","hint":"How old are you? / I am twelve. / zero, one, two …","tokens":["I","am","twelve","years","old."]},{"id":"en-pre-03-fix","type":"correction","skill":"grammar","prompt":"I have twelve years old.","answers":["I am twelve years old."],"explanation":"Yoshni I am twelve tarzida aytamiz. Inglizchada yosh uchun I have twelve demaymiz. Years old iborasi qo‘shilishi mumkin. 13–19 sonlarida -teen, 20, 30, 40 kabi o‘nliklarda -ty farqiga e’tibor bering. Thirteen va thirty bir xil emas. Telefon raqamida har bir raqam alohida o‘qiladi. Zero nolning aniq nomidir; oh telefon raqamlarida ham uchraydi.","hint":"How old are you? / I am twelve. / zero, one, two …"},{"id":"en-pre-03-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["o‘n ikki","o‘n uch","o‘ttiz","raqam yoki son"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"How old are you? / I am twelve. / zero, one, two …","left":["twelve","thirteen","thirty","number"],"options":["o‘n ikki","o‘n uch","o‘ttiz","raqam yoki son"]},{"id":"en-pre-03-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."},{"id":"en-pre-03-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["twelve","thirteen","thirty","number"],"options":["twelve years old","thirteen students","thirty minutes","phone number"],"answers":["twelve years old","thirteen students","thirty minutes","phone number"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Sonlar, yosh va telefon raqami — vaziyat","text":"Aziz is twelve. His sister is thirteen. They join a sports club. There are thirty students at the club. The teacher writes their names and ages. Aziz gives a short practice number: one, two, zero, five. It is not his real phone number.","sentences":["Aziz is twelve.","His sister is thirteen.","They join a sports club.","There are thirty students at the club.","The teacher writes their names and ages.","Aziz gives a short practice number: one, two, zero, five.","It is not his real phone number."],"questions":[{"id":"en-pre-03-reading0","type":"choice","skill":"reading","prompt":"Aziz necha yoshda?","answers":["twelve"],"explanation":"Aziz is twelve jumlasini tekshiring.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["twelve","thirteen","thirty"]},{"id":"en-pre-03-reading1","type":"choice","skill":"reading","prompt":"To‘garakda nechta o‘quvchi bor?","answers":["thirty"],"explanation":"Thirty o‘ttizni bildiradi.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["thirty","thirteen","twelve"]},{"id":"en-pre-03-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["Aziz is twelve.","His sister is thirteen.","They join a sports club.","There are thirty students at the club.","The teacher writes their names and ages.","Aziz gives a short practice number: one, two, zero, five.","It is not his real phone number."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"My name is Aziz. I am twelve years old. My sister is thirteen. Please write this practice number: one, two, zero, five. There are thirty students in our club.","audio":"/english-course/v7.23/en-pre-03.mp3","synthetic":true,"questions":[{"id":"en-pre-03-listening0","type":"choice","skill":"listening","prompt":"Azizning singlisi necha yoshda?","answers":["thirteen"],"explanation":"Sister is thirteen — teen urg‘usini ajrating.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["thirteen","thirty","three"]},{"id":"en-pre-03-listening1","type":"choice","skill":"listening","prompt":"Mashq raqami qaysi?","answers":["1205"],"explanation":"One, two, zero, five shu tartibda aytiladi.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["1205","1250","1025"]},{"id":"en-pre-03-audio-table"