insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-04','en-pre-04',null,0,4,'published',1,'{"id":"en-pre-04","baseId":"en-pre-04","revision":1,"level":"PRE","levelIndex":0,"order":4,"title":"Sana, hafta kunlari va vaqt","objective":"Oddiy uchrashuvning kuni va vaqtini tushunasiz.","context":"Kutubxonadagi mashg‘ulotning jadvali e’lon qilinadi.","prerequisites":["en-pre-03"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi.","It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir.","Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz."],"pattern":"on Monday / at nine o’clock / It is nine thirty.","examples":["The lesson is on Monday.","We meet at nine o’clock.","It is nine thirty.","Friday is a school day.","The club starts at ten.","Today is Tuesday."],"vocabulary":[{"id":"en-pre-04-v0","term":"Monday","meaning":"dushanba","ipa":"/ˈmʌndeɪ/","collocation":"on Monday","example":"The lesson is on Monday."},{"id":"en-pre-04-v1","term":"Friday","meaning":"juma","ipa":"/ˈfraɪdeɪ/","collocation":"on Friday","example":"Friday is a school day."},{"id":"en-pre-04-v2","term":"today","meaning":"bugun","ipa":"/təˈdeɪ/","collocation":"today is Tuesday","example":"Today is Tuesday."},{"id":"en-pre-04-v3","term":"start","meaning":"boshlanmoq","ipa":"/stɑːt/","collocation":"start at ten","example":"The club starts at ten."}],"visuals":[{"kind":"timetable","title":"Ma’no va tuzilish","items":["on Monday / at nine o’clock / It is nine thirty.","The lesson is on Monday.","We meet at nine o’clock."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Kutubxonadagi mashg‘ulotning jadvali e’lon qilinadi.","It is nine thirty.","The club starts at ten."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Friday is a school day.","audio":"/english-course/v7.23/en-pre-04-dictation.mp3"},"exercises":[{"id":"en-pre-04-choice","type":"choice","skill":"grammar","prompt":"Aniq soat oldidan qaysi predlog ishlatiladi?","answers":["at"],"explanation":"At nine — aniq soat.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["at","on","in"]},{"id":"en-pre-04-gap","type":"grammarFill","skill":"grammar","prompt":"We meet ___ Monday.","answers":["on"],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty."},{"id":"en-pre-04-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The lesson is on Monday."],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty.","tokens":["The","lesson","is","on","Monday."]},{"id":"en-pre-04-fix","type":"correction","skill":"grammar","prompt":"The club starts on nine.","answers":["The club starts at nine."],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty."},{"id":"en-pre-04-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["dushanba","juma","bugun","boshlanmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"on Monday / at nine o’clock / It is nine thirty.","left":["Monday","Friday","today","start"],"options":["dushanba","juma","bugun","boshlanmoq"]},{"id":"en-pre-04-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."},{"id":"en-pre-04-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["The lesson is on Monday."],"tokens":["The","lesson","is","on","Monday."],"hint":"on Monday / at nine o’clock / It is nine thirty.","explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi."},{"id":"en-pre-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Harf, tovush va ismni harflab aytish: Ismni harflab aytishni so‘rash uchun qaysi gap mos?","answers":["How do you spell it?"],"explanation":"Spell harfma-harf aytishni bildiradi.","hint":"My name is … / How do you spell it? / A — L — I","options":["How do you spell it?","How old are you?","Where are you?"],"recap":true,"sourceLesson":"Harf, tovush va ismni harflab aytish"},{"id":"en-pre-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Salomlashish va o‘zingizni tanishtirish: Ertalab o‘qituvchi bilan salomlashish uchun qaysi gap mos?","answers":["Good morning."],"explanation":"Morning ertalab degani.","hint":"Hello. I’m … / Nice to meet you. / See you.","options":["Good morning.","Good night.","Goodbye."],"recap":true,"sourceLesson":"Salomlashish va o‘zingizni tanishtirish"},{"id":"en-pre-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Sonlar, yosh va telefon raqami: 30 sonining nomini tanlang.","answers":["thirty"],"explanation":"Thirty — uchta o‘nlik.","hint":"How old are you? / I am twelve. / zero, one, two …","options":["thirty","thirteen","three"],"recap":true,"sourceLesson":"Sonlar, yosh va telefon raqami"}],"reading":{"title":"Sana, hafta kunlari va vaqt — vaziyat","text":"The reading club meets on Monday. It starts at nine o’clock. On Friday, the club starts at nine thirty. Lola writes both times in her notebook. Today is Tuesday, so there is no club meeting today. The next meeting is on Friday.","sentences":["The reading club meets on Monday.","It starts at nine o’clock.","On Friday, the club starts at nine thirty.","Lola writes both times in her notebook.","Today is Tuesday, so there is no club meeting today.","The next meeting is on Friday."],"questions":[{"id":"en-pre-04-reading0","type":"choice","skill":"reading","prompt":"Dushanbadagi mashg‘ulot qachon boshlanadi?","answers":["nine o’clock"],"explanation":"Monday uchun nine o’clock yozilgan.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["nine o’clock","nine thirty","ten o’clock"]},{"id":"en-pre-04-reading1","type":"choice","skill":"reading","prompt":"Keyingi uchrashuv qaysi kun?","answers":["Friday"],"explanation":"The next meeting is on Friday.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["Friday","Tuesday","Monday"]},{"id":"en-pre-04-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["The reading club meets on Monday.","It starts at nine o’clock.","On Friday, the club starts at nine thirty.","Lola writes both times in her notebook.","Today is Tuesday, so there is no club meeting today.","The next meeting is on Friday."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Hello, reading club. Our next meeting is on Friday at nine thirty. Please bring a notebook. Today is Tuesday. There is no meeting today.","audio":"/english-course/v7.23/en-pre-04.mp3","synthetic":true,"questions":[{"id":"en-pre-04-listening0","type":"choice","skill":"listening","prompt":"Uchrashuv kuni qaysi?","answers":["Friday"],"explanation":"Next meeting is on Friday deyiladi.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["Friday","Tuesday","Sunday"]},{"id":"en-pre-04-listening1","type":"choice","skill":"listening","prompt":"Uchrashuv soati qaysi?","answers":["9:30"],"explanation":"Nine thirty — 9:30.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["9:30","9:00","10:30"]},{"id":"en-pre-04-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Friday","9:30"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"on Monday / at nine o’clock / It is nine thirty.","rows":["Kun","Vaqt"]},{"id":"en-pre-04-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Friday is a school day."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"on Monday / at nine o’clock / It is nine thirty.","audio":"/english-course/v7.23/en-pre-04-dictation.mp3","transcript":"Friday is a school day."}]},"writing":{"task":"Sinf to‘garagi uchun kun, boshlanish soati va olib kelinadigan buyumni yozing.","audience":"Sinfdagi sherigingiz","minWords":8,"maxWords":40,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Our club is on Monday. We meet at ten o’clock. Please bring a notebook.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["The lesson is on Monday.","We meet at nine o’clock.","It is nine thirty."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Uchrashuv kuni va vaqtini ayting. Sherigingizdan When? deb qayta so‘rang.","seconds":20,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sinf to‘garagi uchun kun, boshlanish soati va olib kelinadigan buyumni yozing.","exit":[[{"id":"en-pre-04-exit0","type":"grammarFill","skill":"grammar","prompt":"We meet ___ Friday.","answers":["on"],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty."},{"id":"en-pre-04-exit1","type":"grammarFill","skill":"grammar","prompt":"The lesson starts ___ ten.","answers":["at"],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty."},{"id":"en-pre-04-exit2","type":"grammarFill","skill":"grammar","prompt":"9:30 ni so‘z bilan yozing.","answers":["nine thirty"],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty."},{"id":"en-pre-04-exit3","type":"choice","skill":"grammar","prompt":"Kun nomining to‘g‘ri yozilishini tanlang.","answers":["Monday"],"explanation":"Kun nomi bosh harf bilan boshlanadi.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["Monday","monday","MONday"]},{"id":"en-pre-04-exit4","type":"choice","skill":"grammar","prompt":"Today nimani anglatadi?","answers":["bugun"],"explanation":"Today hozirgi kun.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["bugun","ertaga","kecha"]}],[{"id":"en-pre-04-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We meet at nine o’clock."],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty.","tokens":["We","meet","at","nine","o’clock."]},{"id":"en-pre-04-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The lesson starts ___ ten.","answers":["at"],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty."},{"id":"en-pre-04-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Friday is a school day."],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty.","tokens":["Friday","is","a","school","day."]},{"id":"en-pre-04-exit-b3","type":"choice","skill":"grammar","prompt":"Kun nomining to‘g‘ri yozilishini tanlang.","answers":["Monday"],"explanation":"Kun nomi bosh harf bilan boshlanadi.","hint":"on Monday / at nine o’clock / It is nine thirty.","options":["Monday","monday","MONday"]},{"id":"en-pre-04-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Today is Tuesday."],"explanation":"Hafta kunlari inglizchada bosh harf bilan yoziladi: Monday, Tuesday. Kun uchun on, aniq soat uchun at ishlatiladi. It is nine o’clock soat to‘qqizni bildiradi. Nine thirty 9:30 uchun sodda, aniq shakldir. Sana aytishda tartib sonlari kerak bo‘ladi: first, second, third. Dastlab kun va soatni ajratib olishni mashq qilamiz.","hint":"on Monday / at nine o’clock / It is nine thirty.","tokens":["Today","is","Tuesday."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE