insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-05','en-pre-05',null,0,5,'published',1,'{"id":"en-pre-05","baseId":"en-pre-05","revision":1,"level":"PRE","levelIndex":0,"order":5,"title":"Yo‘riqnomalar va gap bo‘laklari","objective":"Listen, read, write, choose buyruqlarini tushunasiz va ot, fe’l, sifatni ajratasiz.","context":"O‘qituvchi yangi mashqni tushuntiradi.","prerequisites":["en-pre-04"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi.","Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is.","Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi."],"pattern":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","examples":["I read a book.","Please listen to the teacher.","Write your name.","Choose the blue book.","Ali is a student.","The small bag is blue."],"vocabulary":[{"id":"en-pre-05-v0","term":"read","meaning":"o‘qimoq","ipa":"/riːd/","collocation":"read a book","example":"I read a book."},{"id":"en-pre-05-v1","term":"write","meaning":"yozmoq","ipa":"/raɪt/","collocation":"write a name","example":"Write your name."},{"id":"en-pre-05-v2","term":"choose","meaning":"tanlamoq","ipa":"/tʃuːz/","collocation":"choose a book","example":"Choose the blue book."},{"id":"en-pre-05-v3","term":"blue","meaning":"ko‘k","ipa":"/bluː/","collocation":"a blue bag","example":"Choose the blue book."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["Ega → fe’l → to‘ldiruvchi / I → read → a book.","I read a book.","Please listen to the teacher."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘qituvchi yangi mashqni tushuntiradi.","Write your name.","Ali is a student."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Choose the blue book.","audio":"/english-course/v7.23/en-pre-05-dictation.mp3"},"exercises":[{"id":"en-pre-05-choice","type":"choice","skill":"grammar","prompt":"Blue qaysi gap bo‘lagi?","answers":["adjective"],"explanation":"Blue kitobning rangini tasvirlaydi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["adjective","verb","pronoun"]},{"id":"en-pre-05-gap","type":"grammarFill","skill":"grammar","prompt":"I ___ a book.","answers":["read"],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book."},{"id":"en-pre-05-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I read a book."],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","tokens":["I","read","a","book."]},{"id":"en-pre-05-fix","type":"correction","skill":"grammar","prompt":"Book I read a.","answers":["I read a book."],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book."},{"id":"en-pre-05-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["o‘qimoq","yozmoq","tanlamoq","ko‘k"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","left":["read","write","choose","blue"],"options":["o‘qimoq","yozmoq","tanlamoq","ko‘k"]},{"id":"en-pre-05-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."}],"reading":{"title":"Yo‘riqnomalar va gap bo‘laklari — vaziyat","text":"The teacher says, “Read a book.” Ali chooses a small blue book. Lola writes her name in a notebook. Then they listen to the teacher. The teacher asks them to choose a picture. A book is a thing; read is an action; blue describes a colour.","sentences":["The teacher says, “Read a book.","” Ali chooses a small blue book.","Lola writes her name in a notebook.","Then they listen to the teacher.","The teacher asks them to choose a picture.","A book is a thing; read is an action; blue describes a colour."],"questions":[{"id":"en-pre-05-reading0","type":"choice","skill":"reading","prompt":"Ali qanday kitob tanlaydi?","answers":["a small blue book"],"explanation":"Small va blue kitobning belgilaridir.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["a small blue book","a large red book","a green notebook"]},{"id":"en-pre-05-reading1","type":"choice","skill":"reading","prompt":"Read qaysi vazifani bajaradi?","answers":["an action"],"explanation":"Read o‘qish amalini ifodalaydi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["an action","a colour","a person"]},{"id":"en-pre-05-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["The teacher says, “Read a book.","” Ali chooses a small blue book.","Lola writes her name in a notebook.","Then they listen to the teacher.","The teacher asks them to choose a picture.","A book is a thing; read is an action; blue describes a colour."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Please listen. Read the first sentence. Write your name. Then choose the blue book. Do not choose the red book. Thank you.","audio":"/english-course/v7.23/en-pre-05.mp3","synthetic":true,"questions":[{"id":"en-pre-05-listening0","type":"choice","skill":"listening","prompt":"Qaysi kitob tanlanadi?","answers":["blue"],"explanation":"Choose the blue book deyiladi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["blue","red","green"]},{"id":"en-pre-05-listening1","type":"choice","skill":"listening","prompt":"Nima yoziladi?","answers":["your name"],"explanation":"Write your name — ism yozish.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["your name","a number","a colour"]},{"id":"en-pre-05-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["blue","name"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","rows":["Kitob rangi","Yoziladigan ma’lumot"]},{"id":"en-pre-05-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Choose the blue book."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","audio":"/english-course/v7.23/en-pre-05-dictation.mp3","transcript":"Choose the blue book."}]},"writing":{"task":"Sherigingiz uchun uchta sodda mashq yo‘riqnomasini yozing.","audience":"Sinfdagi sherigingiz","minWords":8,"maxWords":40,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Read the sentence. Write your name. Choose the blue book.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I read a book.","Please listen to the teacher.","Write your name."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Uch yo‘riqnomani ayting; sherigingiz bajarishini so‘rang. So‘ng rollarni almashtiring.","seconds":20,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sherigingiz uchun uchta sodda mashq yo‘riqnomasini yozing.","exit":[[{"id":"en-pre-05-exit0","type":"grammarFill","skill":"grammar","prompt":"Yozing degan buyruqni inglizcha yozing.","answers":["write"],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book."},{"id":"en-pre-05-exit1","type":"grammarFill","skill":"grammar","prompt":"I ___ a book.","answers":["read"],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book."},{"id":"en-pre-05-exit2","type":"grammarFill","skill":"grammar","prompt":"___ the blue book.","answers":["Choose"],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book."},{"id":"en-pre-05-exit3","type":"choice","skill":"grammar","prompt":"Book qanday so‘z?","answers":["noun"],"explanation":"Book buyumni nomlaydi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["noun","verb","adverb"]},{"id":"en-pre-05-exit4","type":"choice","skill":"grammar","prompt":"Oddiy gap tartibini tanlang.","answers":["I read a book."],"explanation":"Ega avval, fe’l undan keyin.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["I read a book.","Read I book a.","A I book read."]}],[{"id":"en-pre-05-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Please listen to the teacher."],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","tokens":["Please","listen","to","the","teacher."]},{"id":"en-pre-05-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I ___ a book.","answers":["read"],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book."},{"id":"en-pre-05-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Choose the blue book."],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","tokens":["Choose","the","blue","book."]},{"id":"en-pre-05-exit-b3","type":"choice","skill":"grammar","prompt":"Book qanday so‘z?","answers":["noun"],"explanation":"Book buyumni nomlaydi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","options":["noun","verb","adverb"]},{"id":"en-pre-05-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The small bag is blue."],"explanation":"Listen — tinglang, read — o‘qing, write — yozing, choose — tanlang. Oddiy buyruqda fe’lning asosiy shakli ishlatiladi. Ot narsa yoki odamni nomlaydi: book, student. Sifat uning xususiyatini aytadi: blue book. Fe’l ish yoki holatni ifodalaydi: read, is. Oddiy inglizcha gapda ega ko‘pincha fe’ldan oldin turadi: I read a book. Ega gapning kim yoki nima haqida ekanini ko‘rsatadi.","hint":"Ega → fe’l → to‘ldiruvchi / I → read → a book.","tokens":["The","small","bag","is","blue."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-pre-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-pre-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-pre-06','en-pre-06',null,0,6,'published',1,'{"id":"en-pre-06","baseId":"en-pre-06","revision":1,"level":"PRE","levelIndex":0,"order":6,"title":"O‘qish qoidalari va birinchi loyiha","objective":"Harf yozuvi va talaffuz bir xil emasligini misollarda ko‘rsatib, qisqa tanishtirasiz.","context":"Kursning birinchi haftasi yakunida har bir o‘quvchi o‘zini tanishtiradi.","prerequisites":["en-pre-05"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Cat so‘zidagi a ko‘pincha /æ/, name so‘zidagi a esa /eɪ/ bo‘ladi. Oxirgi e ayrim so‘zlarda talaffuz qilinmasa ham oldingi unlini o‘zgartiradi. Bu har bir so‘z uchun mutlaq qoida emas.","/iː/ va /ɪ/ farqi sheep va ship kabi so‘zlarda ma’noni o‘zgartiradi. IPA talaffuzni aniqlashtiruvchi belgilar tizimidir.","Tanishtirishda ism, yosh, sinf va bitta qiziqishni mantiqiy tartibda ayting. Tushunmasangiz, Please say it again deb qayta so‘rashingiz mumkin."],"pattern":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","examples":["My name is Aziz.","I am twelve years old.","I am in class six.","Please say it again.","This is a ship.","I like books."],"vocabulary":[{"id":"en-pre-06-v0","term":"ship","meaning":"kema","ipa":"/ʃɪp/","collocation":"a big ship","example":"This is a ship."},{"id":"en-pre-06-v1","term":"sheep","meaning":"qo‘y","ipa":"/ʃiːp/","collocation":"a white sheep","example":"In our English lesson, I learn that ship and sheep are different words."},{"id":"en-pre-06-v2","term":"again","meaning":"yana","ipa":"/əˈɡen/","collocation":"say it again","example":"Please say it again."},{"id":"en-pre-06-v3","term":"class","meaning":"sinf","ipa":"/klɑːs/","collocation":"class six","example":"I am in class six."}],"visuals":[{"kind":"sound","title":"Ma’no va tuzilish","items":["cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","My name is Aziz.","I am twelve years old."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Kursning birinchi haftasi yakunida har bir o‘quvchi o‘zini tanishtiradi.","I am in class six.","This is a ship."]}],"pronunciation":{"focus":"Ship va sheep yozuvini solishtiring. /iː/ faqat cho‘zilish bilan emas, til holati bilan ham /ɪ/ dan farq qiladi.","text":"Please say it again.","audio":"/english-course/v7.23/en-pre-06-dictation.mp3"},"exercises":[{"id":"en-pre-06-choice","type":"choice","skill":"grammar","prompt":"Ship va sheep haqida qaysi fikr to‘g‘ri?","answers":["Ular boshqa so‘zlar va tovushlari farq qiladi."],"explanation":"/ɪ/ va /iː/ ikki turli unli tovush.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","options":["Ular boshqa so‘zlar va tovushlari farq qiladi.","Ularning ma’nosi doim bir xil.","Ular faqat yozuvda farq qiladi."]},{"id":"en-pre-06-gap","type":"grammarFill","skill":"grammar","prompt":"Please say it ___.","answers":["again"],"explanation":"Cat so‘zidagi a ko‘pincha /æ/, name so‘zidagi a esa /eɪ/ bo‘ladi. Oxirgi e ayrim so‘zlarda talaffuz qilinmasa ham oldingi unlini o‘zgartiradi. Bu har bir so‘z uchun mutlaq qoida emas. /iː/ va /ɪ/ farqi sheep va ship kabi so‘zlarda ma’noni o‘zgartiradi. IPA talaffuzni aniqlashtiruvchi belgilar tizimidir. Tanishtirishda ism, yosh, sinf va bitta qiziqishni mantiqiy tartibda ayting. Tushunmasangiz, Please say it again deb qayta so‘rashingiz mumkin.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/"},{"id":"en-pre-06-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["My name is Aziz."],"explanation":"Cat so‘zidagi a ko‘pincha /æ/, name so‘zidagi a esa /eɪ/ bo‘ladi. Oxirgi e ayrim so‘zlarda talaffuz qilinmasa ham oldingi unlini o‘zgartiradi. Bu har bir so‘z uchun mutlaq qoida emas. /iː/ va /ɪ/ farqi sheep va ship kabi so‘zlarda ma’noni o‘zgartiradi. IPA talaffuzni aniqlashtiruvchi belgilar tizimidir. Tanishtirishda ism, yosh, sinf va bitta qiziqishni mantiqiy tartibda ayting. Tushunmasangiz, Please say it again deb qayta so‘rashingiz mumkin.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","tokens":["My","name","is","Aziz."]},{"id":"en-pre-06-fix","type":"correction","skill":"grammar","prompt":"My name Aziz.","answers":["My name is Aziz."],"explanation":"Cat so‘zidagi a ko‘pincha /æ/, name so‘zidagi a esa /eɪ/ bo‘ladi. Oxirgi e ayrim so‘zlarda talaffuz qilinmasa ham oldingi unlini o‘zgartiradi. Bu har bir so‘z uchun mutlaq qoida emas. /iː/ va /ɪ/ farqi sheep va ship kabi so‘zlarda ma’noni o‘zgartiradi. IPA talaffuzni aniqlashtiruvchi belgilar tizimidir. Tanishtirishda ism, yosh, sinf va bitta qiziqishni mantiqiy tartibda ayting. Tushunmasangiz, Please say it again deb qayta so‘rashingiz mumkin.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/"},{"id":"en-pre-06-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["kema","qo‘y","yana","sinf"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","left":["ship","sheep","again","class"],"options":["kema","qo‘y","yana","sinf"]},{"id":"en-pre-06-picture","type":"picture","skill":"vocabulary","prompt":"“Book” yozilgan predmetni tanlang.","options":["book","clock","chair"],"answers":["book"],"hint":"Book — kitob.","explanation":"Kitobning sahifalari bor. Clock — soat, chair — stul."},{"id":"en-pre-06-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["ship","sheep","again","class"],"options":["a big ship","a white sheep","say it again","class six"],"answers":["a big ship","a white sheep","say it again","class six"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"O‘qish qoidalari va birinchi loyiha — vaziyat","text":"My name is Aziz. I am twelve years old. I am in class six. I like books and pictures of ships. In our English lesson, I learn that ship and sheep are different words. When I do not understand a word, I ask, “Please say it again.”","sentences":["My name is Aziz.","I am twelve years old.","I am in class six.","I like books and pictures of ships.","In our English lesson, I learn that ship and sheep are different words.","When I do not understand a word, I ask, “Please say it again.","”"],"questions":[{"id":"en-pre-06-reading0","type":"choice","skill":"reading","prompt":"Aziz nechanchi sinfda?","answers":["class six"],"explanation":"I am in class six jumlasiga qarang.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","options":["class six","class five","class seven"]},{"id":"en-pre-06-reading1","type":"choice","skill":"reading","prompt":"Aziz tushunmasa nima qiladi?","answers":["asks to hear it again"],"explanation":"U qayta aytishni so‘raydi.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","options":["asks to hear it again","closes the book","leaves the class"]},{"id":"en-pre-06-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","options":["My name is Aziz.","I am twelve years old.","I am in class six.","I like books and pictures of ships.","In our English lesson, I learn that ship and sheep are different words.","When I do not understand a word, I ask, “Please say it again.","”"]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Hello. My name is Aziz. I am twelve. I am in class six. I like books. I can spell my name: A, Z, I, Z. Please say your name again.","audio":"/english-course/v7.23/en-pre-06.mp3","synthetic":true,"questions":[{"id":"en-pre-06-listening0","type":"choice","skill":"listening","prompt":"Ism nechta harf bilan aytiladi?","answers":["four"],"explanation":"A, Z, I, Z — to‘rtta harf.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","options":["four","three","five"]},{"id":"en-pre-06-listening1","type":"choice","skill":"listening","prompt":"Azizning qiziqishi nima?","answers":["books"],"explanation":"I like books deyiladi.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","options":["books","football","music"]},{"id":"en-pre-06-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["six","twelve"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","rows":["Sinf","Yosh"]},{"id":"en-pre-06-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Please say it again."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"cat /kæt/ ≠ name /neɪm/; ship /ʃɪp/ ≠ sheep /ʃiːp/","audio":"/english-course/v7.23/en-pre-06-dictation.mp3","transcript":"Please say it again."}]},"writing":{"task":"Birinchi loyiha: ism, yosh, sinf va qiziqishingiz haqida 4–5 gap yozing.","audience":"Sinfdagi sherigingiz","minWords":8,"maxWords":40,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"My name is Lola. I am thirteen years old. I am in class seven. I like books. Nice to meet you.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["My name is Aziz.","I am twelve years old.","I am in class six."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"O‘zingizni tanishtiring, ismingizni harflang va bitta savolga javob bering.","seconds":