:["I","like","books."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-pre-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-pre-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":true,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-01','en-a1-01',null,1,1,'published',1,'{"id":"en-a1-01","baseId":"en-a1-01","revision":1,"level":"A1","levelIndex":1,"order":1,"title":"Kim haqida gapiryapmiz? Olmoshlar","objective":"Takrorlangan ismlarni ega va obyekt olmoshlari bilan almashtirasiz.","context":"Lola yangi sinfdoshlarini va kim kimga yordam berishini tanishtiradi.","prerequisites":["en-pre-06"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi.","Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me.","You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi."],"pattern":"Lola → she; Ali → he; Ali helps Lola → He helps her.","examples":["She is my classmate.","He helps me.","We read together.","The teacher knows us.","I sit next to him.","They talk to her."],"vocabulary":[{"id":"en-a1-01-v0","term":"together","meaning":"birga","ipa":"/təˈɡeðə/","collocation":"read together","example":"We read together."},{"id":"en-a1-01-v1","term":"help","meaning":"yordam bermoq","ipa":"/help/","collocation":"help me","example":"He helps me."},{"id":"en-a1-01-v2","term":"know","meaning":"bilmoq, tanimoq","ipa":"/nəʊ/","collocation":"know a person","example":"The teacher knows us."},{"id":"en-a1-01-v3","term":"next to","meaning":"yonida","ipa":"/nekst tuː/","collocation":"sit next to","example":"I sit next to him."}],"visuals":[{"kind":"family","title":"Ma’no va tuzilish","items":["Lola → she; Ali → he; Ali helps Lola → He helps her.","She is my classmate.","He helps me."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Lola yangi sinfdoshlarini va kim kimga yordam berishini tanishtiradi.","We read together.","I sit next to him."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The teacher knows us.","audio":"/english-course/v7.23/en-a1-01-dictation.mp3"},"exercises":[{"id":"en-a1-01-choice","type":"choice","skill":"grammar","prompt":"Lola likes books. ___ reads every day.","answers":["She"],"explanation":"Fe’ldan oldin ega olmoshi she kerak.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["She","Her","Him"]},{"id":"en-a1-01-gap","type":"grammarFill","skill":"grammar","prompt":"Ali helps ___. (I)","answers":["me"],"explanation":"I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi. Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me. You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her."},{"id":"en-a1-01-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["She is my classmate."],"explanation":"I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi. Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me. You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","tokens":["She","is","my","classmate."]},{"id":"en-a1-01-fix","type":"correction","skill":"grammar","prompt":"The teacher helps we.","answers":["The teacher helps us."],"explanation":"I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi. Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me. You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her."},{"id":"en-a1-01-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["birga","yordam bermoq","bilmoq, tanimoq","yonida"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","left":["together","help","know","next to"],"options":["birga","yordam bermoq","bilmoq, tanimoq","yonida"]}],"reading":{"title":"Kim haqida gapiryapmiz? Olmoshlar — vaziyat","text":"Lola and Ali are in my class. She likes stories, and he likes science. We read together after school. Our teacher helps us when a word is difficult. I sit next to Ali, so I can talk to him. Lola brings a dictionary. We often ask her for help. They are good friends, and I enjoy learning with them.","sentences":["Lola and Ali are in my class.","She likes stories, and he likes science.","We read together after school.","Our teacher helps us when a word is difficult.","I sit next to Ali, so I can talk to him.","Lola brings a dictionary.","We often ask her for help.","They are good friends, and I enjoy learning with them."],"questions":[{"id":"en-a1-01-reading0","type":"choice","skill":"reading","prompt":"She bu matnda kim?","answers":["Lola"],"explanation":"Oldingi gapda ikki ism bor; stories bilan bog‘langan she — Lola.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["Lola","Ali","the teacher"]},{"id":"en-a1-01-reading1","type":"choice","skill":"reading","prompt":"Ustoz kimga yordam beradi?","answers":["us"],"explanation":"Helps us butun guruhni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["us","him only","her only"]},{"id":"en-a1-01-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["Lola and Ali are in my class.","She likes stories, and he likes science.","We read together after school.","Our teacher helps us when a word is difficult.","I sit next to Ali, so I can talk to him.","Lola brings a dictionary.","We often ask her for help.","They are good friends, and I enjoy learning with them."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Ali is my classmate. He helps me with reading. Lola is our friend. We sit next to her. Our teacher knows us and helps us every day.","audio":"/english-course/v7.23/en-a1-01.mp3","synthetic":true,"questions":[{"id":"en-a1-01-listening0","type":"choice","skill":"listening","prompt":"Readingda kim yordam beradi?","answers":["Ali"],"explanation":"He helps me oldidagi Ali ga tegishli.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["Ali","Lola","a parent"]},{"id":"en-a1-01-listening1","type":"choice","skill":"listening","prompt":"We kimning yonida o‘tiradi?","answers":["Lola"],"explanation":"Lola oldingi gapda aytilib, her bilan davom ettiriladi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["Lola","the teacher","a parent"]},{"id":"en-a1-01-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Ali","Lola"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","rows":["He kim?","Her kim?"]},{"id":"en-a1-01-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The teacher knows us."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","audio":"/english-course/v7.23/en-a1-01-dictation.mp3","transcript":"The teacher knows us."}]},"writing":{"task":"Ikki do‘stingiz haqida yozing. Ismlardan keyin olmoshlar ishlating va kim kimga yordam berishini ayting.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Lola and Ali are my friends. She likes books, and he likes football. We study together at school. They help me with English. I enjoy working with them because our lessons are interesting.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["She is my classmate.","He helps me.","We read together."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Ikki sinfdoshingizni tanishtiring. Sherigingiz Who helps you? deb so‘rasin.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ikki do‘stingiz haqida yozing. Ismlardan keyin olmoshlar ishlating va kim kimga yordam berishini ayting.","exit":[[{"id":"en-a1-01-exit0","type":"grammarFill","skill":"grammar","prompt":"The teacher knows ___. (we)","answers":["us"],"explanation":"I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi. Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me. You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her."},{"id":"en-a1-01-exit1","type":"grammarFill","skill":"grammar","prompt":"I talk to ___. (he)","answers":["him"],"explanation":"I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi. Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me. You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her."},{"id":"en-a1-01-exit2","type":"grammarFill","skill":"grammar","prompt":"___ read together. (Lola and Ali)","answers":["They"],"explanation":"I, you, he, she, it, we, they ega olmoshlaridir: She reads. He erkak, she ayol, it buyum yoki kontekstdagi hayvon uchun ishlatiladi. Me, you, him, her, it, us, them fe’l yoki predlogdan keyingi obyektni bildiradi: Ali helps me. You birlik va ko‘plikda bir xil. We so‘zlovchini ham o‘z ichiga oladi; they so‘zlovchidan boshqa odam yoki narsalarni bildiradi.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her."},{"id":"en-a1-01-exit3","type":"choice","skill":"grammar","prompt":"Qaysi gap to‘g‘ri?","answers":["He helps her."],"explanation":"He — ega; her — obyekt.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["He helps her.","Him helps she.","Her helps him is."]},{"id":"en-a1-01-exit4","type":"choice","skill":"grammar","prompt":"We so‘zlovchini o‘z ichiga oladimi?","answers":["Yes"],"explanation":"We — men va boshqalar.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["Yes","No","Never"]}],[{"id":"en-a1-01-exit-b0","type":"order",