insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-02','en-a1-02',null,1,2,'published',1,'{"id":"en-a1-02","baseId":"en-a1-02","revision":1,"level":"A1","levelIndex":1,"order":2,"title":"To be: ism, kasb va holat","objective":"Am, is, are yordamida odam va narsani tasvirlaysiz.","context":"Kitobxonlar to‘garagining yangi a’zolari tanishadi.","prerequisites":["en-a1-01"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["I bilan am, he/she/it bilan is, you/we/they bilan are ishlatiladi. Bu fe’l ism, holat yoki joyni bog‘laydi.","Inglizcha tasdiq gapda bog‘lovchi fe’lni tashlab ketmang: She is a student. O‘zbekchada hozirgi zamonda bunday fe’l ko‘rinmasligi mumkin.","I’m, he’s, they’re qisqartmalari kundalik nutqda tabiiy. Am, is, are shu darsda have bilan almashtirilmaydi."],"pattern":"I am / he, she, it is / you, we, they are","examples":["I am a student.","Lola is happy.","We are at school.","They are my friends.","The book is new.","You are ready."],"vocabulary":[{"id":"en-a1-02-v0","term":"happy","meaning":"xursand","ipa":"/ˈhæpi/","collocation":"feel happy","example":"Lola is happy."},{"id":"en-a1-02-v1","term":"ready","meaning":"tayyor","ipa":"/ˈredi/","collocation":"be ready","example":"You are ready."},{"id":"en-a1-02-v2","term":"new","meaning":"yangi","ipa":"/njuː/","collocation":"a new book","example":"The book is new."},{"id":"en-a1-02-v3","term":"friend","meaning":"do‘st","ipa":"/frend/","collocation":"my friend","example":"They are my friends."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["I am / he, she, it is / you, we, they are","I am a student.","Lola is happy."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Kitobxonlar to‘garagining yangi a’zolari tanishadi.","We are at school.","The book is new."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"They are my friends.","audio":"/english-course/v7.23/en-a1-02-dictation.mp3"},"exercises":[{"id":"en-a1-02-choice","type":"choice","skill":"grammar","prompt":"I ___ ready.","answers":["am"],"explanation":"I uchun am ishlatiladi.","hint":"I am / he, she, it is / you, we, they are","options":["am","is","are"]},{"id":"en-a1-02-gap","type":"grammarFill","skill":"grammar","prompt":"They ___ my friends.","answers":["are"],"explanation":"I bilan am, he/she/it bilan is, you/we/they bilan are ishlatiladi. Bu fe’l ism, holat yoki joyni bog‘laydi. Inglizcha tasdiq gapda bog‘lovchi fe’lni tashlab ketmang: She is a student. O‘zbekchada hozirgi zamonda bunday fe’l ko‘rinmasligi mumkin. I’m, he’s, they’re qisqartmalari kundalik nutqda tabiiy. Am, is, are shu darsda have bilan almashtirilmaydi.","hint":"I am / he, she, it is / you, we, they are"},{"id":"en-a1-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I am a student."],"explanation":"I bilan am, he/she/it bilan is, you/we/they bilan are ishlatiladi. Bu fe’l ism, holat yoki joyni bog‘laydi. Inglizcha tasdiq gapda bog‘lovchi fe’lni tashlab ketmang: She is a student. O‘zbekchada hozirgi zamonda bunday fe’l ko‘rinmasligi mumkin. I’m, he’s, they’re qisqartmalari kundalik nutqda tabiiy. Am, is, are shu darsda have bilan almashtirilmaydi.","hint":"I am / he, she, it is / you, we, they are","tokens":["I","am","a","student."]},{"id":"en-a1-02-fix","type":"correction","skill":"grammar","prompt":"Lola a student.","answers":["Lola is a student."],"explanation":"I bilan am, he/she/it bilan is, you/we/they bilan are ishlatiladi. Bu fe’l ism, holat yoki joyni bog‘laydi. Inglizcha tasdiq gapda bog‘lovchi fe’lni tashlab ketmang: She is a student. O‘zbekchada hozirgi zamonda bunday fe’l ko‘rinmasligi mumkin. I’m, he’s, they’re qisqartmalari kundalik nutqda tabiiy. Am, is, are shu darsda have bilan almashtirilmaydi.","hint":"I am / he, she, it is / you, we, they are"},{"id":"en-a1-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["xursand","tayyor","yangi","do‘st"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"I am / he, she, it is / you, we, they are","left":["happy","ready","new","friend"],"options":["xursand","tayyor","yangi","do‘st"]}],"reading":{"title":"To be: ism, kasb va holat — vaziyat","text":"I am Aziz, and I am a student. Lola is my friend. She is happy because the reading club is open today. We are at school, and our teacher is in the library. The books are new. Ali and Vali are ready for the first story. It is a short story about a family. We are excited to read it together.","sentences":["I am Aziz, and I am a student.","Lola is my friend.","She is happy because the reading club is open today.","We are at school, and our teacher is in the library.","The books are new.","Ali and Vali are ready for the first story.","It is a short story about a family.","We are excited to read it together."],"questions":[{"id":"en-a1-02-reading0","type":"choice","skill":"reading","prompt":"Ustoz qayerda?","answers":["in the library"],"explanation":"Our teacher is in the library jumlasi joyni beradi.","hint":"I am / he, she, it is / you, we, they are","options":["in the library","at home","in the shop"]},{"id":"en-a1-02-reading1","type":"choice","skill":"reading","prompt":"Kitoblar qanday?","answers":["new"],"explanation":"The books are new — books ko‘plik.","hint":"I am / he, she, it is / you, we, they are","options":["new","old","closed"]},{"id":"en-a1-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"I am / he, she, it is / you, we, they are","options":["I am Aziz, and I am a student.","Lola is my friend.","She is happy because the reading club is open today.","We are at school, and our teacher is in the library.","The books are new.","Ali and Vali are ready for the first story.","It is a short story about a family.","We are excited to read it together."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Hello. I am Malika, your teacher. We are in the library. Lola is happy, and Ali is ready. The books are new. You are all welcome here.","audio":"/english-course/v7.23/en-a1-02.mp3","synthetic":true,"questions":[{"id":"en-a1-02-listening0","type":"choice","skill":"listening","prompt":"Guruh qayerda?","answers":["in the library"],"explanation":"We are in the library deyiladi.","hint":"I am / he, she, it is / you, we, they are","options":["in the library","in the kitchen","in the park"]},{"id":"en-a1-02-listening1","type":"choice","skill":"listening","prompt":"Kim tayyor?","answers":["Ali"],"explanation":"Ali is ready deyiladi.","hint":"I am / he, she, it is / you, we, they are","options":["Ali","Lola","Aziz"]},{"id":"en-a1-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Malika","Ali"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"I am / he, she, it is / you, we, they are","rows":["O‘qituvchi","Tayyor o‘quvchi"]},{"id":"en-a1-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["They are my friends."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"I am / he, she, it is / you, we, they are","audio":"/english-course/v7.23/en-a1-02-dictation.mp3","transcript":"They are my friends."}]},"writing":{"task":"To‘garak a’zosi sifatida o‘zingiz, do‘stingiz, joy va holatingiz haqida yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I am Lola, and I am a student. My friend Ali is here too. We are in the library. The room is quiet, and the books are new. We are ready to read.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I am a student.","Lola is happy.","We are at school."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"O‘zingizni va sherigingizni am/is/are bilan tanishtiring.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"To‘garak a’zosi sifatida o‘zingiz, do‘stingiz, joy va holatingiz haqida yozing.","exit":[[{"id":"en-a1-02-exit0","type":"grammarFill","skill":"grammar","prompt":"She ___ happy.","answers":["is"],"explanation":"I bilan am, he/she/it bilan is, you/we/they bilan are ishlatiladi. Bu fe’l ism, holat yoki joyni bog‘laydi. Inglizcha tasdiq gapda bog‘lovchi fe’lni tashlab ketmang: She is a student. O‘zbekchada hozirgi zamonda bunday fe’l ko‘rinmasligi mumkin. I’m, he’s, they’re qisqartmalari kundalik nutqda tabiiy. Am, is, are shu darsda have bilan almashtirilmaydi.","hint":"I am / he, she, it is / you, we, they are"},{"id":"en-a1-02-exit1","type":"grammarFill","skill":"grammar","prompt":"We ___ at school.","answers":["are"],"explanation":"I bilan am, he/she/it bilan is, you/we/they bilan are ishlatiladi. Bu fe’l ism, holat yoki joyni bog‘laydi. Inglizcha tasdiq gapda bog‘lovch